// The web build's stand-in for vault creation (phase3-web-client task 32).
//
// # Absent, not hidden — and this file is what makes that literally true
//
// `decisions.md` 2026-07-26 ("Web capability set") is normative: the 24-word
// recovery phrase is **never generated by, displayed by, or typed into served
// code**. Hiding the affordance would not satisfy that — the phrase-rendering
// code would still be in the bundle, one devtools breakpoint or one route
// override away, and `protocol.md` §7 gives a leaked phrase no in-app remedy:
// it survives every password change and there is no rotation command. One
// exposure is permanent.
//
// So the build **substitutes this module for `src/screens/CreateVault`**, the
// same mechanism the platform seam uses (`web/vite.config.ts`). The real
// component, the phrase grid, the BIP-39 wordlist it autocompletes against and
// the confirm step never enter the web bundle at all. `scripts/check-web-no-phrase.mjs`
// greps the built output to keep it that way.
//
// # Why it renders anything at all
//
// `App.tsx` compiles unchanged for both clients, so the `create-vault` stage
// still exists as a type. It is unreachable on web — `Welcome`'s create CTA is
// omitted by the capability descriptor (`vaultCreation` is absent) — but "should
// be unreachable" is a claim, and a blank render would make a routing bug look
// like a blank screen. This says what happened instead.

import { useTranslation } from "react-i18next";
import { CenteredCard } from "../../../src/components/primitives/CenteredCard";

export interface CreateVaultProps {
  [key: string]: unknown;
}

export function CreateVault(_props: CreateVaultProps) {
  const { t } = useTranslation();
  return (
    // The container anchor (phase3-web-client task 100). A scenario asserts
    // "absent, not disabled" POSITIVELY — it finds this surface and reads its
    // `data-surface` — rather than by the absence of a selector, which is
    // indistinguishable from a selector somebody renamed.
    <CenteredCard>
      <h1
        style={{ fontFamily: "var(--font-sans)", fontSize: "var(--text-xl)" }}
        data-testid="web.unavailable"
        data-surface="creation"
      >
        {t("web.unavailableHere.title")}
      </h1>
      <p style={{ color: "var(--fg-3)" }} data-testid="web.creation-absent">
        {t("web.unavailableHere.creation")}
      </p>
    </CenteredCard>
  );
}
